/**
 * withAndroidR8 -- enable R8 minification (obfuscation) + resource shrinking in release builds.
 * Google Play flags "DEX code optimization is below our threshold" (obfuscation) otherwise.
 *
 * Applied to the generated android/gradle.properties (gitignored, regenerated by `expo prebuild`).
 * Add -keep rules via a config plugin that appends to the generated android/app/proguard-rules.pro
 * (do not edit it by hand: prebuild regenerates it). See README "Release builds: R8 obfuscation".
 */
const fs = require('fs')
const path = require('path')
const { withGradleProperties, withDangerousMod } = require('expo/config-plugins')
const setGradleProperty = require('./setGradleProperty')

const PROPS = {
  'android.enableMinifyInReleaseBuilds': 'true',
  'android.enableShrinkResourcesInReleaseBuilds': 'true',
}

// Keep rules, appended to the generated android/app/proguard-rules.pro (idempotent via marker).
const MARKER = '# --- withAndroidR8 keep rules ---'
const KEEP_RULES = `${MARKER}
# react-native-device-info reflects on InstallReferrerClient.newBuilder(Context)
-keep class com.android.installreferrer.api.** { *; }
`

function withKeepRules(config) {
  return withDangerousMod(config, [
    'android',
    (config) => {
      const file = path.join(config.modRequest.platformProjectRoot, 'app', 'proguard-rules.pro')
      const current = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : ''
      if (!current.includes(MARKER)) fs.writeFileSync(file, `${current}\n${KEEP_RULES}`)
      return config
    },
  ])
}

module.exports = function withAndroidR8(config) {
  config = withKeepRules(config)
  return withGradleProperties(config, (config) => {
    for (const [key, value] of Object.entries(PROPS)) {
      setGradleProperty(config.modResults, key, value)
    }
    return config
  })
}
